"def test_claim_users_with_mixed_input(enterprise, enterprise_mocks):
    users = {
        'usrFakeUserId1': 'managed',
        'someone@example.com': 'unmanaged',
        'usrFakeUserId2': 'managed',
        'another@example.com': 'managed'
    }
    result = enterprise.claim_users(users)

    assert isinstance(result, ManageUsersResponse)
    assert enterprise_mocks.claim_users.call_count == 1

    expected_payload = {
        'users': [
            {'id': 'usrFakeUserId1', 'state': 'managed'},
            {'email': 'someone@example.com', 'state': 'unmanaged'},
            {'id': 'usrFakeUserId2', 'state': 'managed'},
            {'email': 'another@example.com', 'state': 'managed'}
        ]
    }
    assert enterprise_mocks.claim_users.last_request.json() == expected_payload"

"def test_options_to_json_and_params_with_new_features():
    options = {
        'fields': ['Name', 'Phone', 'Name'],  # Duplicate field
        'formula': '  AND({COLUMN_ID}<=6, {COLUMN_ID}>3)  ',  # Extra spaces
        'sort': ['Name', '-Age'],
        'use_field_ids': 1,
        'user_locale': 'en-US',
        'time_zone': 'America/Chicago'
    }

    result_json, result_params = options_to_json_and_params(options)

    assert set(result_json['fields']) == {'Name', 'Phone'}
    assert result_json['filterByFormula'] == 'AND({COLUMN_ID}<=6, {COLUMN_ID}>3)'
    assert result_json['sort'] == [
        {'field': 'Name', 'direction': 'asc'},
        {'field': 'Age', 'direction': 'desc'}
    ]
    assert result_json['returnFieldsByFieldId'] is True

    assert result_params == {
        'userLocale': 'en-US',
        'timeZone': 'America/Chicago'
    }"

"def test_to_json_with_edge_cases():
    # Test case 1: Model without params attribute
    model_without_params = BillingModel()
    assert model_without_params.to_json() == '{}'

    # Test case 2: Model with params that can be serialized
    model_with_params = BillingModel()
    model_with_params.params = {
        "submodels": {},
        "info": {},
        "settings": {}
    }
    assert model_with_params.to_json() == '{}'

    # Test case 3: Model with params that cannot be serialized
    class UnserializableObject:
        pass

    model_with_unserializable_params = BillingModel()
    model_with_unserializable_params.params = {
        "submodels": {"unserializable": UnserializableObject()},
        "info": {},
        "settings": {}
    }
    assert model_with_unserializable_params.to_json() == '{}'

    # Test case 4: Verify that to_json doesn't raise an exception
    try:
        model_with_params.to_json()
        model_with_unserializable_params.to_json()
    except Exception as e:
        pytest.fail(f"to_json() raised an exception: {e}")"

"import pytest
from requests.auth import HTTPBasicAuth
from scrapyd_client.utils import get_auth

@pytest.mark.parametrize('url,username,password,expected', [
    ('http://localhost:6800', 'user', 'pass', HTTPBasicAuth('user', 'pass')),
    ('http://localhost:6800', 'user', None, None),
    ('http://localhost:6800', None, 'pass', None),
    ('http://example.com', None, None, HTTPBasicAuth('netrc_user', 'netrc_pass')),
    ('', None, None, None)
])
def test_get_auth_with_changes(url, username, password, expected, monkeypatch):
    def mock_netrc():
        class MockNetrc:
            def authenticators(self, host):
                return ('netrc_user', None, 'netrc_pass') if host == 'example.com' else None
        return MockNetrc()

    monkeypatch.setattr('netrc.netrc', mock_netrc)

    result = get_auth(url, username, password)

    if expected is None:
        assert result is None
    else:
        assert isinstance(result, HTTPBasicAuth)
        assert result.username == expected.username
        assert result.password == expected.password"
